/** 「无」= 编年史里没有对应事件，不进编号索引（否则几行共用一个键） */
const BY_EVENT_ID = new Map<string, NavalBattleParam>(
    NAVAL_BATTLE_PARAMS.filter((p) => p.eventId && p.eventId !== '无').map((p) => [p.eventId, p]),
);
const BY_NAME = new Map<string, NavalBattleParam>();
for (const p of NAVAL_BATTLE_PARAMS) {
    for (const n of [p.name, ...(p.aliases ?? [])]) if (!BY_NAME.has(n)) BY_NAME.set(n, p);
}

/** 这个名字（含别名）在表里对应几场不同的仗：>1 表示同名不同年，只按名字查不可靠 */
export function countNavalBattlesNamed(name: string): number {
    return NAVAL_BATTLE_PARAMS.filter((p) => p.name === name || (p.aliases ?? []).includes(name)).length;
}

/** 按事件 ID（支持 chron:evt_xxxx 或 evt_xxxx）或战役名查找核定海战参数 */
export function findNavalBattleParam(eventId?: string | null, battleName?: string | null): NavalBattleParam | null {
    if (eventId) {
        const raw = eventId.startsWith('chron:') ? eventId.slice(6) : eventId;
        const hit = BY_EVENT_ID.get(raw);
        if (hit) return hit;
    }
    if (battleName) {
        const clean = battleName.replace(/^公元前?\d+年\s*/, '').trim();
        const hit = BY_NAME.get(battleName) ?? BY_NAME.get(clean);
        if (hit) return hit;
    }
    return null;
}
